#--------------------------------------------------------------
# Script to generate the transition associated with or whithout NAS.
#--------------------------------------------------------------
# Author: Lirot Hélène
# Date: 2025/07/03
# Description:
# This Python script requires data generated by qPCR_pathogen_analysis.R.
#--------------------------------------------------------------

import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt
from matplotlib.colors import LinearSegmentedColormap

# Path to the CSV file (adjust as needed)
file_path = 'Profiles_transition_NAS.csv'

# Read the CSV file with the correct separator and handle spaces
data = pd.read_csv(file_path, sep=';', engine='python')

# Remove the first column by its index (index 0)
transitions = data.drop(data.columns[0], axis=1)

# Clean columns that may contain unwanted spaces
transitions['Probability_state'] = transitions['Probability_state'].str.replace(' ', '')  # Remove spaces
transitions['Probability_state'] = transitions['Probability_state'].str.replace(',', '.')  # Replace commas with dots
transitions['Probability_state'] = transitions['Probability_state'].astype(float)  # Convert to float

# Remove rows where Probability_state == 0
transitions = transitions[transitions['Probability_state'] > 0]

# Ensure the required columns exist
if 'From' not in transitions.columns or 'To' not in transitions.columns:
    raise ValueError("The columns 'From' or 'To' are missing from the DataFrame transitions.")

# Create a directed graph
G = nx.DiGraph()

# Add nodes and edges with weights to the graph
for row in transitions.itertuples(index=False):
    source, target, probability = row.From, row.To, row.Probability_state
    if source != target:  # Exclude transitions where source == target
        G.add_edge(source, target, weight=probability)

# Define node positions with NAS groups close together
pos = {
    "A": (2, 3.75),
    "B": (3, 3.75),
    
    "C_no_NAS": (1, 3),
    "C_NAS": (0.75, 2),
    
    "D_no_NAS": (4, 3),
    "D_NAS": (4.25, 2),
    
    "E_no_NAS": (1, 1),
    "E_NAS": (2, 0.5),
    
    "F_no_NAS": (4, 1),
    "F_NAS": (3, 0.5)
}

# Define colors for nodes
node_colors = {
    "A": '#8da0cb',  # Blue
    "B": '#e0c900',  # Dark yellow
    
    "C_no_NAS": '#66c2a5',  # Green
    "C_NAS": '#66c2a5', 
    
    "D_no_NAS": '#fc8d62',  # Orange
    "D_NAS": '#fc8d62', 
    
    "E_no_NAS": '#a6d854',  # Light green
    "E_NAS": '#a6d854',
    
    "F_no_NAS": '#e78ac3',  # Pink
    "F_NAS": '#e78ac3'
}

# Assign node colors based on labels
node_color_list = [node_colors.get(node, '#000000') for node in G.nodes]

# Plot the graph
plt.figure(figsize=(14, 10))
edges = G.edges(data=True)

# Draw nodes with defined colors
nx.draw_networkx_nodes(G, pos, node_size=2800, node_color=node_color_list)
   
# Draw node labels
# Custom labels with line break after the first letter only
custom_labels = {
    node: node[0] + '\n' + node[2:] if '_' in node else node
    for node in G.nodes()
}
nx.draw_networkx_labels(G, pos, labels=custom_labels, font_size=13, font_weight='bold')

# Normalize weights for color mapping
weights = [data['weight'] for _, _, data in edges]  # Use 'weight' instead of 'Probability_state'
max_weight = max(weights)

import matplotlib.colors as mcolors
# Liste des couleurs du gris clair (#cccccc) au noir (#000000)
grey_to_black = ['#cccccc', '#999999', '#666666', '#333333', '#000000']

# Créer un colormap continu
cmap = mcolors.LinearSegmentedColormap.from_list('grey_to_black', grey_to_black, N=256)

# Normalize weights for color mapping
norm = plt.Normalize(vmin=min(weights), vmax=max(weights))

# Draw curved edges with arrows colored based on weight
ax = plt.gca()
for u, v, data in edges:
    weight = data['weight'] * 18  # Increase edge thickness
    color = cmap(norm(data['weight']))
    rad = 0.3  # Curve of the arrow

    nx.draw_networkx_edges(
        G, pos, edgelist=[(u, v)], arrowstyle='-|>', arrowsize=30, edge_color=[color],
        connectionstyle=f'arc3,rad={rad}', width=weight, ax=ax, node_size=2900
    )

# Add a color bar to show the weight scale
sm = plt.cm.ScalarMappable(cmap=cmap, norm=norm)
sm.set_array([])
plt.colorbar(sm, ax=plt.gca(), label='Transition weights')

plt.title("")
plt.axis('off')  # Hide axes

# Save the graph as an image file
output_path = 'Figure_supp_mat_9.png'
plt.savefig(output_path, format='png', dpi=300)
